INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-6', 'hayat-pharmacy-insights-6', 'Al-Hayat Pharmacy Industry Brief #6: Pharmacist Medication Review', 'تقرير صيدلية الحياة التخصصي #6: مراجعة دوائية مع الصيدلي', 'Key operational benchmarks and best practices from Al-Hayat Pharmacy in Sanabis.', 'أبرز المعايير التشغيلية وأفضل الممارسات من صيدلية الحياة في Sanabis.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery. Our Pharmacist Medication Review division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع. يساعد قسم مراجعة دوائية مع الصيدلي المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery.</p><p>Our Pharmacist Medication Review division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع.</p><p>يساعد قسم مراجعة دوائية مع الصيدلي المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'pharmacy', '{"pharmacy","Sanabis","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '54 days', false, now() - interval '54 days', now()) ON CONFLICT (id) DO NOTHING;
